const _bg=Color(0xFF07111F),_panel=Color(0xFF101A30),_line=Color(0xFF27355D),_purple=Color(0xFF8B5CFF),_muted=Color(0xFFA7B0C7),_orange=Color(0xFFFFA24B),_blue=Color(0xFF42A5FF),_lime=Color(0xFF79FF45);
class VehicleCenterPage extends StatefulWidget{const VehicleCenterPage({super.key,required this.plate,required this.title});final String plate,title;@override State<VehicleCenterPage> createState()=>_VehicleCenterPageState();}
class _VehicleCenterPageState extends State<VehicleCenterPage>{bool loading=true;int km=0;List<dynamic> reminders=[],upcoming=[];String get vid=>QrDraft.vehicleId.trim().isNotEmpty?QrDraft.vehicleId.trim():OnboardingDraft.vehicleId.trim();String get owner=>OnboardingDraft.userId.trim();Map<String,String> get h=>{'Content-Type':'application/json','x-owner-id':owner};
 @override void initState(){super.initState();load();}Future<void> load()async{try{final a=await http.get(Uri.parse('${QrBackend.baseUrl}/api/vehicles/$vid/reminders'),headers:h),b=await http.get(Uri.parse('${QrBackend.baseUrl}/api/vehicles/$vid/maintenance'),headers:h);final x=jsonDecode(a.body),y=jsonDecode(b.body);if(mounted)setState((){reminders=x['reminders']??[];km=(y['currentKm']??0) as int;upcoming=y['upcoming']??[];loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}
 Future<void> editDate(String type,String label)async{final now=DateTime.now(),d=await showDatePicker(context:context,firstDate:now.subtract(const Duration(days:365)),lastDate:DateTime(now.year+10),initialDate:now);if(d==null)return;final date='${d.year.toString().padLeft(4,'0')}-${d.month.toString().padLeft(2,'0')}-${d.day.toString().padLeft(2,'0')}';await http.put(Uri.parse('${QrBackend.baseUrl}/api/vehicles/$vid/reminders'),headers:h,body:jsonEncode({'type':type,'dueDate':date}));await load();}
 Map<String,dynamic>? item(String type){for(final x in reminders){if(x['reminder_type']==type)return Map<String,dynamic>.from(x);}return null;}String dateText(dynamic x){if(x==null)return 'Tarih ekle';final s=x['due_date'].toString();return s.length>=10?s.substring(0,10):s;}String left(dynamic x){if(x==null)return 'Hatırlatma oluştur';final n=x['daysLeft'];return n==null?'':n<0?'Süresi geçti':n==0?'Bugün son gün':'$n gün kaldı';}
 @override Widget build(BuildContext context){final top=MediaQuery.paddingOf(context).top;if(loading)return const Scaffold(backgroundColor:_bg,body:Center(child:CircularProgressIndicator()));final inspection=item('inspection'),insurance=item('traffic_insurance'),casco=item('casco');return Scaffold(backgroundColor:_bg,body:RefreshIndicator(onRefresh:load,child:ListView(padding:EdgeInsets.fromLTRB(16,top+12,16,28),children:[Row(children:[IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back,color:Colors.white)),const SizedBox(width:4),const Text('Aracım',style:TextStyle(color:Colors.white,fontSize:27,fontWeight:FontWeight.w900))]),const SizedBox(height:12),Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:_panel,borderRadius:BorderRadius.circular(24),border:Border.all(color:_purple)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.title,style:const TextStyle(color:Colors.white,fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(widget.plate,style:const TextStyle(color:_muted,fontSize:14)),const SizedBox(height:16),Row(children:[const Icon(Icons.speed_rounded,color:_lime),const SizedBox(width:8),Text(km>0?'$km km':'KM girilmedi',style:const TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.w900)),const Spacer(),TextButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>MaintenancePage(plate:widget.plate,title:widget.title))).then((_)=>load()),child:const Text('KM Güncelle'))])])),const SizedBox(height:18),const Text('Belgeler & Hatırlatmalar',style:TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:10),_Reminder(icon:Icons.fact_check_outlined,color:_purple,title:'Muayene',date:dateText(inspection),subtitle:left(inspection),onTap:()=>editDate('inspection','Muayene')),_Reminder(icon:Icons.shield_outlined,color:_blue,title:'Trafik Sigortası',date:dateText(insurance),subtitle:left(insurance),onTap:()=>editDate('traffic_insurance','Trafik Sigortası')),_Reminder(icon:Icons.verified_user_outlined,color:_orange,title:'Kasko',date:dateText(casco),subtitle:left(casco),onTap:()=>editDate('casco','Kasko')),const SizedBox(height:14),Row(children:[const Expanded(child:Text('Yaklaşan Bakımlar',style:TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.w900))),TextButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>MaintenancePage(plate:widget.plate,title:widget.title))),child:const Text('Bakım Geçmişi'))]),if(upcoming.isEmpty)Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:_panel,borderRadius:BorderRadius.circular(18)),child:const Text('Henüz yaklaşan bakım bulunmuyor. Bakım kaydı eklediğinde burada takip edilir.',style:TextStyle(color:_muted)))else ...upcoming.take(3).map((x)=>_Maintenance(data:Map<String,dynamic>.from(x))),const SizedBox(height:14),Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:_purple.withValues(alpha:.12),borderRadius:BorderRadius.circular(18),border:Border.all(color:_purple.withValues(alpha:.35))),child:const Row(children:[Icon(Icons.notifications_active_outlined,color:_purple),SizedBox(width:10),Expanded(child:Text('Cepqar tarih ve kilometre bilgilerine göre yaklaşan işlemleri takip eder.',style:TextStyle(color:_muted,fontSize:12.5)))]) )] )));}}
class _Reminder extends StatelessWidget{const _Reminder({required this.icon,required this.color,required this.title,required this.date,required this.subtitle,required this.onTap});final IconData icon;final Color color;final String title,date,subtitle;final VoidCallback onTap;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:9),child:InkWell(onTap:onTap,borderRadius:BorderRadius.circular(18),child:Container(padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:_panel,borderRadius:BorderRadius.circular(18),border:Border.all(color:_line)),child:Row(children:[Container(width:44,height:44,decoration:BoxDecoration(color:color.withValues(alpha:.13),borderRadius:BorderRadius.circular(14)),child:Icon(icon,color:color)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w900)),const SizedBox(height:3),Text(subtitle,style:const TextStyle(color:_muted,fontSize:11.5))])),Text(date,style:TextStyle(color:date=='Tarih ekle'?_purple:Colors.white,fontSize:12,fontWeight:FontWeight.w800)),const SizedBox(width:4),const Icon(Icons.chevron_right,color:_muted)]))));}
class _Maintenance extends StatelessWidget{const _Maintenance({required this.data});final Map<String,dynamic> data;@override Widget build(BuildContext context){final r=NumberFormat.simple(data['remainingKm']);return Container(margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:_panel,borderRadius:BorderRadius.circular(18),border:Border.all(color:_line)),child:Row(children:[const Icon(Icons.build_circle_outlined,color:_orange,size:34),const SizedBox(width:12),Expanded(child:Text(data['label']?.toString()??'Bakım',style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w900))),Text(r,style:const TextStyle(color:_orange,fontWeight:FontWeight.w900))]));}}
class NumberFormat{static String simple(dynamic n){final x=int.tryParse('$n')??0;return x<=0?'Bakım zamanı':'$x km kaldı';}}
